import{_ as a}from"./chunks/rayrai_pbr_texture_maps.CoEV03PI.js";import{_ as t,o as s,c as r,a5 as i}from"./chunks/framework.DrDMl0tG.js";const x=JSON.parse('{"title":"Rayrai Example: PBR Texture Maps","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_pbr_texture_maps.md","filePath":"sections/examples/rayrai/rayrai_pbr_texture_maps.md"}'),o={name:"sections/examples/rayrai/rayrai_pbr_texture_maps.md"};function n(l,e,d,p,h,c){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rayrai-example-pbr-texture-maps" tabindex="-1">Rayrai Example: PBR Texture Maps <a class="header-anchor" href="#rayrai-example-pbr-texture-maps" aria-label="Permalink to &quot;Rayrai Example: PBR Texture Maps&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Loads six Khronos glTF Sample Assets in one interactive rayrai scene. The example is an asset inspector for textured PBR import, HDR image-based lighting, normal maps, metallic-roughness maps, occlusion maps, emissive maps, and mixed asset scales/units.</p><p>The six assets are CC0; each keeps its license file under <code>rsc/rayrai/pbr</code>. The example leaves out <code>DamagedHelmet</code> and <code>AntiqueCamera</code> from the same folder: the first is licensed for non-commercial use only (CC BY-NC 4.0) and the second carries a UX3D trademark, so renders of them cannot be published freely. Check an asset&#39;s license file before loading it into a scene you share.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+a+'" alt="rayrai_pbr_texture_maps example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_pbr_texture_maps</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_pbr_texture_maps</span></span></code></pre></div><p>On Windows, run <code>rayrai_pbr_texture_maps.exe</code> instead. This example renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>.</p><p>Pass <code>--screenshot PATH</code> to render with a hidden window, wait until every asset has loaded, save the final image as a PNG, and exit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_pbr_texture_maps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --screenshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/pbr_texture_maps.png</span></span></code></pre></div><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads these glTF assets from <code>rsc/rayrai/pbr</code>: <code>FlightHelmet</code>, <code>SciFiHelmet</code>, <code>Lantern</code>, <code>BoomBox</code>, <code>Avocado</code>, and <code>WaterBottle</code>.</li><li>Applies a fixed per-asset scale so that each model&#39;s longest authored extent has about the same preview size, and lays the assets out in two rows, the helmets above the other four, that slowly turn about the vertical axis.</li><li>Keeps assets upright in rayrai&#39;s and RaiSim&#39;s Z-up coordinate convention.</li><li>Uses the Ultra quality preset with tuned exposure and shadows and one additional warm point light.</li><li>Adds <code>rsc/rayrai/hdr/polyhaven/potsdamer_platz_1k.hdr</code> as an HDR environment. The HDR is used both for the visible background and for PBR reflections through environment, irradiance, prefiltered environment, and BRDF lookup textures.</li><li>Lets the user orbit the camera to inspect the assets; this is the preferred example for checking whether imported PBR texture maps are actually active.</li></ul>',16)])])}const _=t(o,[["render",n]]);export{x as __pageData,_ as default};
